end

function App:go(name, args)
    if self:requestScenePool(name,args) then return end
    local old = self.scene
    if old and old.exit then old:exit() end
    self.scene=nil
    self.input:clearUI()
    if self:requestScenePool(name,args) then return end
    local mod = require(App.SCENES[name] or name)
