function App:update(dt)
    self.callbackDt=dt
    self:sampleFrameRate(dt)
    self:netPump() -- receive before any pool maintenance or drawing
    if self.initialAssets and self:advanceInitialAssets(dt) then return end
    if self.poolNext then
