        if self.paint then self.paint:free(true) end
        self.L:free()
        for _, n in ipairs(self.sparks) do G.releaseLater(n) end
        return
    end
    if self.paint then self.paint:free() end
    self.L:free()
    for _, n in ipairs(self.sparks) do G.release(n) end
