        local hover=st=='burst' and 65 or st=='skill' and 38 or 25
        if st=='skill' and t>f.move.startup then hover=hover*(1-U.clamp((t-f.move.startup)/f.move.recovery,0,1)) end
        oy=oy+hover+5*math.sin(self.app.t*6+f.id)
    end
    self.tilt, self.sx, self.sy, self.ox, self.oy = tilt, sx, sy, ox, oy
    local provider=Registry.provider(self.key)
    local deliveredVictim=f.foe and (f.foe.key=='furina' or f.foe.key=='kamisatoayaka') and ((st=='thrown' and f.foe.state=='throw') or (f.foe.state=='burst' and f.foe.cinematicConfirmed))
    if (provider and provider.groundedFrames) or deliveredVictim then
        tilt,sx,sy,ox,oy=0,1,1,0,0
        if provider and provider.rootOffset then oy=provider.rootOffset(self) end
        if provider and provider.displayScale then sx=provider.displayScale(self);sy=sx end
        self.tilt,self.sx,self.sy,self.ox,self.oy=tilt,sx,sy,ox,oy
