        local len = r * 0.42
        local rot = (ang + 90) * face + (face < 0 and 180 or 0)
        local delay = k
        local col = (i % 3 == 1) and WHITE or ec
        self:spawn(W, {shape = ELLIPSE, x = px, y = py, w = len, h = w, rot = rot, col = col, a = 0.95,
