        local yy = y + 60 + i * 60
        self:spawn(W, {shape = RECT, x = x - face * 40, y = yy, w = 120, h = 4, col = i == 2 and ec or WHITE, a = 0.7,
                       to = {x = x - face * 240, sx = 0.2, a = 0}, dur = 0.22})
    end
