function FX:update()
    local list = self.fading
    if not list then return end
    local now = self.app.t
    for i = #list, 1, -1 do
        local t = list[i]
        if t.fadeAt and now >= t.fadeAt then
            t.fadeAt = nil
            t:tween({fontColor = G.col(255, 255, 255, 0), anchoredPositionY = (t.ty or 0) + 40}, 0.25, 'InQuad', function() t:on(false) end)
            table.remove(list, i)
        end
    end
end

function FX:flash(col, a, dur)
    local S = self.screen
    local app = self.app
    col = col or WHITE
    self:spawn(S, {shape = RECT, x = 0, y = 0, w = app.coverW, h = app.coverH, col = col, a = a or 0.8, to = {a = 0}, dur = dur or 0.18, ease = 'OutQuad'})
