    {'ControllerNormalAttackKey', 'pad', B.LP, 'ok'}, {'ControllerInteractKey', 'pad', B.HP},
    {'ControllerCharacterSkill1Key', 'pad', B.SK}, {'ControllerCharacterSkill2Key', 'pad', B.BU},
    {'ControllerSprintKey', 'pad', B.DA}, {'ControllerJumpKey', 'pad', B.U},
