function I.new(app)
    local self = setmetatable({app = app, pads = {newPad(), newPad()}, menuQ = {}, rep = {}, held = {},
                               dev = 'pc', padOwner = 1, buttons = {}, touchOn = false, mouseOn = false}, I)
    self:attach()
    return self
end

function I:attach()
