    local E = env.Enum
    local host = env.host
    local n = 0
    for _, b in ipairs(BINDS) do
        local okd, dn = pcall(function() return E.KeyEventType[b[1] .. 'Down'] end)
        local oku, up = pcall(function() return E.KeyEventType[b[1] .. 'Up'] end)
