-- clean opposite directions (SOCD): left+right = neutral, up+down = up
local function clean(m)
    if m & B.L ~= 0 and m & B.R ~= 0 then m = m & ~(B.L | B.R) end
    if m & B.U ~= 0 and m & B.D ~= 0 then m = m & ~B.D end
    return m
end

-- once per 60 Hz tick
function I:tick()
