local S = {}
S.__index = S

local function cycle(list, cur, d)
    local i = 1
    for k, v in ipairs(list) do if v == cur then i = k end end
    return list[(i - 1 + d) % #list + 1]
end

function S.new(app)
    local self = setmetatable({app = app, t = 0}, S)
