        {id = 'touch', label = '触屏按键', value = function() return ({auto = '自动', on = '开', off = '关'})[st.touch] end,
         left = function() st.touch = cycle({'auto', 'on', 'off'}, st.touch, -1) end, right = function() st.touch = cycle({'auto', 'on', 'off'}, st.touch, 1) end},
        {id = 'back', label = '返回'},
