end

local INFO = {
    shake = {'SCREEN SHAKE', '屏幕震动', '重击、元素爆发与击倒时的镜头震动。'},
    sfx = {'SOUND', '音效', '游戏内音效开关。'},
    cpu = {'CPU LEVEL', '电脑难度', '对战电脑时对手的反应速度、防御与连段长度。'},
    rounds = {'ROUNDS', '获胜局数', '先赢下这么多回合的一方获胜。'},
    time = {'TIME', '回合时间', '时间到时，剩余体力比例高的一方赢下回合。'},
    touch = {'TOUCH', '触屏按键', '自动：只在手机上显示屏幕按键。'},
    back = {'BACK', '返回', '回到主菜单。'},
}

function S:draw()
