__loaders['gf_scene_result'] = function()
-- Results, fighting-game style: the winner large in a victory pose on the left over an
-- element slab; on the right a slanted panel with VICTORY, the winner's name huge, the score,
-- hairline stat rows counting up, and the next step (rematch / next arcade fight / menu).
local G = require('gf_gfx')
local U = require('gf_util')
local UI = require('gf_ui')
local K = require('gf_kits')
local Art = require('gf_art')
local Show = require('gf_show')
local Paint = require('gf_paint')

local S = {}
S.__index = S

function S.new(app, res)
    local self = setmetatable({app = app, res = res, t = 0}, S)
    local fa = res.args or {}
    local st = fa.stage and Paint.available[fa.stage] and fa.stage or (Paint.available.mondstadt and 'mondstadt' or next(Paint.available))
    if st then self.bd = app:backdrop(st) end
    self.win = res.winner
    local wkey = res.chars[self.win or 1]
    self.show = Show.new(app.layers.world)
    self.showKey=wkey
    self.showBuilt=false
    self.back = G.layer(app.layers.back)
    self.L = G.layer(app.layers.ui)
    self.arcade = fa.arcade
    local items
    local humanWon = self.win == 1 or (fa.cpu and not fa.cpu[1] and not fa.cpu[2] and self.win ~= nil)
    if self.arcade then
        if self.win == 1 then
            if require('gf_mode_arcade').recordWin(self.arcade,res.stats[1]) then
                self.cleared = true
                items = {{id = 'menu', label = '返回主菜单', sub = '角色挑战完成'}}
            else
                items = {{id = 'next', label = '下一战', sub = ('第 %d / %d 战'):format(self.arcade.step + 1, #self.arcade.ladder)},
                         {id = 'menu', label = '返回主菜单'}}
            end
        else
            items = {{id = 'retry', label = '再次挑战', sub = '从这一战重新开始'}, {id = 'menu', label = '返回主菜单'}}
        end
    elseif res.mode == 'online' then
        local won = self.win == res.side
        items = {{id = 'lobby', label = '返回联机大厅', sub = won and '胜利！对手可以在大厅里再次准备' or '在大厅里准备，再战一局'},
                 {id = 'menu', label = '返回主菜单'}}
    else
        items = {{id = 'again', label = '再战一局'}, {id = 'select', label = '重新选择角色'}, {id = 'menu', label = '返回主菜单'}}
    end
    self.menu = UI.menu(app, app.layers.ui, items, {x = app.W / 2 - 340, y = -170, w = 460, h = 64, gap = 8, size = 28,
        accent = UI.ECOL[(Art.byKey[wkey] or {}).element] or UI.GOLD,
        onPick = function(id) self:pick(id) end})
    app.audio:play(self.win == 1 and app.audio.ID.okBig or app.audio.ID.close)
    return self
end

function S:pick(id)
    local app = self.app
    local fa = self.res.args or {}
    if id == 'menu' then
        if app.net then
            if app.net.io.stop then app.net.io.stop() end
            app.net=nil
        end
        app:travel('menu')
    elseif id == 'lobby' then
        if fa.teamRoster then
            if app.teamSelectionIO then app.teamSelectionIO.reset();app.teamSelectionIO.stop() end
            if app.net and app.net.io.stop then app.net.io.stop() end;app.net=nil
            app:travel('select',{teamPreview=true,teamOnline=true})
        else app:travel('online') end
    elseif id == 'again' then app:travel('vs', fa)
    elseif id == 'select' then
        if fa.teamRoster then app:travel('select',{teamPreview=true,teamOnline=fa.online})
        else app:travel('select', {mode = fa.mode == 'arcade' and 'arcade' or fa.mode, cpu = fa.cpu and fa.cpu[2] and true or false}) end
    elseif id == 'next' then
        require('gf_mode_arcade').advance(self.arcade)
        app:travel('vs', {arcade = self.arcade})
    elseif id == 'retry' then app:travel('vs', {arcade = self.arcade})
    end
end

function S:tick()
    self.t = self.t + 1 / 60
    if not self.showBuilt then
        local app=self.app
        self.show:set(self.showKey,app.quality=='lo' and 'lo' or 'hi',self.win and 'special' or 'hurt',-app.W/2+430,-app.H/2+60,1.7,1,0)
        self.showBuilt=true
    elseif self.bd then self.bd:step(300) end
    self.menu:input(self.app.input:menu())
end

function S:draw()
    local app = self.app
    local W, H = app.W, app.H
    if self.bd then self.bd:draw(0.5, {10, 14, 32}) end
    local t = self.t
    local k = U.ease.outCubic(U.clamp(t / 0.5, 0, 1))
    local res = self.res
    local wch = self.win and Art.byKey[res.chars[self.win]]
    local ec = wch and (UI.ECOL[wch.element] or K.elementColor[wch.element]) or UI.GOLD
    -- background: winner slab on the left, navy panel on the right, streaks, constellation
    local B = self.back
    B:begin()
    UI.slab(B, -W / 2 + 330 - (1 - k) * 600, 0, 760, H * 1.9, U.mix(ec, UI.NAVY, 0.7), 0.7, UI.SLANT)
    UI.stripes(B, -W / 2 + 330 - (1 - k) * 600, 0, 620, H * 1.9, 16, UI.WHITE, 0.03, UI.SLANT)
    UI.slab(B, W / 2 - 300 + (1 - k) * 700, 0, 900, H * 1.9, UI.NAVY, 0.84, UI.SLANT)
    local ex = W / 2 - 300 - 450 / math.cos(math.rad(UI.SLANT)) + (1 - k) * 700
    UI.slab(B, ex, 0, 3, H * 2, UI.GOLD, 0.8, UI.SLANT)
    UI.slab(B, ex - 28, 0, 12, H * 2, ec, 0.6, UI.SLANT)
    UI.constellation(B, -W / 2 + 430, -H / 2 + 330, 300, t * 6, UI.WHITE, 0.8)
    B:shape(G.ELLIPSE, -W / 2 + 430, -H / 2 + 300, 760, 760, ec, 0.22, 0, 0.5)
    for i = 1, 7 do
        local yy = -H / 2 + i * H / 7.5
        local xx = ((t * (420 + (i % 3) * 200) + i * 300) % (W + 600)) - W / 2 - 300
        B:rect(xx, yy, 240 + (i % 3) * 120, 2, i % 2 == 0 and UI.WHITE or ec, 0.1, UI.SLANT)
    end
    B:label(self.win and 'VICTORY' or 'DRAW', -W / 2 + 520, H / 2 - 120, 1400, 260, 210, UI.WHITE, 'l', nil, 0.07 * k)
    B:finish()
    -- right panel: title block
    local L = self.L
    L:begin()
    local px = W / 2 - 340
    local ty = H / 2 - 130
    local head = self.cleared and 'CHALLENGE CLEAR' or (self.win == nil and 'DRAW GAME' or 'VICTORY')
    local nm = self.cleared and '挑战完成' or (self.win == nil and '平局' or wch.name)
    L:label(UI.track(head), px, ty + 70, 520, 28, 18, UI.GOLD, 'l', nil, k)
    local n = L:label(nm, px + (1 - k) * 80, ty + 4, 520, 110, 92, UI.WHITE, 'l', nil, k)
    if wch then UI.badge(L, wch.element, px - 260 + (utf8.len(nm) or 3) * 92 + 56, ty + 4, 60, k) end
    L:rect(px, ty - 54, 520 * k, 3, ec, k)
    L:label(self.arcade and ('街机得分　%d'):format(self.arcade.score) or (res.teamRemaining and ('剩余角色　%d : %d'):format(res.teamRemaining[1],res.teamRemaining[2]) or ('比分　%d : %d'):format(res.wins[1], res.wins[2])),
            px, ty - 84, 520, 30, 22, UI.CREAM, 'l', nil, k)
    -- stats: hairline rows, numbers count up
    local st = res.stats[self.win or 1]
    local rows = {{'最大连击', st.maxCombo}, {'造成伤害', st.damage}, {'元素爆发', st.bursts}, {'成功防御', st.blocks}}
    for i, r in ipairs(rows) do
        local y = ty - 140 - (i - 1) * 40
        local a = U.ease.outCubic(U.clamp((t - 0.25 - i * 0.06) / 0.3, 0, 1))
        local v = r[2] or 0
        local shown = math.floor(v * U.clamp((t - 0.35 - i * 0.06) / 0.6, 0, 1) + 0.5)
        L:label(r[1], px + (1 - a) * 40, y, 520, 36, 20, UI.GREY, 'l', nil, a)
        L:label(tostring(shown), px + (1 - a) * 40, y, 520, 36, 24, UI.WHITE, 'r', nil, a)
        L:rect(px, y - 19, 520, 1, UI.WHITE, 0.14 * a)
    end
    UI.prompt(L, W / 2 - 300, -H / 2 + 40, 'J', '确认', 1, 'ok')
    L:finish()
    self.menu:draw(k)
end

function S:exit()
    self.show:free()
    self.back:free()
    self.L:free()
    self.menu:free()
end

return S
end
__loaders['gf_scene_select'] = function()
-- Character select, fighting-game layout: both sides' fighters stand large on the left and
-- right over slanted element-coloured slabs with a giant ghost name; names, element badges and
-- skills sit at the top; the roster is an 8 x 2 strip of portrait cards on a dark band at the
-- bottom with tilted 1P / 2P / CPU tags. Then a stage picker whose backdrop is the stage itself.
-- Modes: arcade (pick yourself, the ladder picks the rest), versus vs CPU (pick both),
-- versus 2P (both players pick at once), training.
local G = require('gf_gfx')
local U = require('gf_util')
local UI = require('gf_ui')
local K = require('gf_kits')
local Art = require('gf_art')
local Show = require('gf_show')
local Stage = require('gf_stage')
local Paint = require('gf_paint')
local O = require('gf_online')

local S = {}
S.__index = S

local MAX_COLS = 8
local CARD_W, CARD_H = 104, 128
local GAP = 8
local PCOL = {{255, 196, 92}, {98, 200, 255}}     -- 1P gold, 2P / CPU cyan

function S.new(app, args)
    if args and args.teamPreview then return require('gf_scene_team_select').new(app,args) end
    local self = setmetatable({app = app, args = args or {}, t = 0, phase = 'chars'}, S)
    local previewRoster=self.args.previewRoster or self.args.mode~='online'
    self.roster = previewRoster and require('gf_selection_art').roster or Art.roster
    self.previewArt = previewRoster and require('gf_selection_art') or Art
    self.focused={false,false}
    local n = #self.roster
    self.cur = {1, math.min(n, 8)}
    self.done = {false, false}
    self.who = 1                            -- in "pick both" modes: whose pick it is
    self.mode = self.args.mode or 'versus'
    self.twoP = (self.mode == 'versus' and self.args.cpu == false)
    self.stageI = 1
    if self.mode == 'online' then
        self.net=app:netOn(); O.leaveMatch(self.net)
        self.net.me.selecting=true; self.net.me.ready=false
        self.cur[1]=self.net.me.char
        self.stageI=1
    end
    self.tier = app.quality == 'lo' and 'lo' or 'hi'
    local key = Paint.available.inazuma and 'inazuma' or next(Paint.available)
    if key then self.bd = app:backdrop(key) end
    self.shows = {Show.new(app.layers.world), Show.new(app.layers.world)}
    self.Lback = G.layer(app.layers.back)          -- slabs and card backs: behind the fighters
    self.cardsG = G.group(app.layers.world)
    self.cards = {}
    self.built = 0
    self.L = G.layer(app.layers.ui)
    self:bindAreas()
    self.shown = {nil, nil}
    return self
end

function S:cardPos(i)
    local app = self.app
    local COLS=math.min(MAX_COLS,#self.roster)
    local row = (i - 1) // COLS
    local col = (i - 1) % COLS
    local totalW = COLS * CARD_W + (COLS - 1) * GAP
    local x = -totalW / 2 + CARD_W / 2 + col * (CARD_W + GAP)
    local y = -app.H / 2 + 272 - row * (CARD_H + GAP)
    return x, y
end

-- one small bitmap per card, built two per frame (keeps every frame under the budget)
function S:buildCards()
    local n = #self.roster
    local k = 0
    while self.built < n and k < 1 do
        self.built = self.built + 1
        local i = self.built
        local c = self.roster[i]
        local x, y = self:cardPos(i)
        local b = G.bitmap(self.cardsG)
        b:drawMany({{img = self.previewArt.face(c.key), ox = 0, oy = -40, s = 2.9}})
        b.node:pos(x, y):on(true)
        self.cards[i] = b
        k = k + 1
    end
end

function S:bindAreas()
    local app = self.app
    self.cardAreas={}
    for i in ipairs(self.roster) do
        local x, y = self:cardPos(i)
        local idx = i
        self.cardAreas[i]=app.input:area(x, y, CARD_W, CARD_H, {down = function()
            local p = self:activePlayer()
            if self.phase == 'chars' and p then
                if self.cur[p] == idx and self.focused[p] then self:confirm(p)
                else self.cur[p] = idx;self.focused[p]=true;app.audio:play(app.audio.ID.move) end
            end
        end})
    end
end

function S:resize()
    self.shown={nil,nil}
    for i,b in pairs(self.cards) do local x,y=self:cardPos(i);b.node:pos(x,y) end
    for i,b in pairs(self.cardAreas or {}) do local x,y=self:cardPos(i);self.app.input:moveArea(b,x,y,CARD_W,CARD_H) end
end

function S:activePlayer()
    if self.mode=='online' then return not self.done[1] and 1 or nil end
    if self.twoP then
        if not self.done[1] then return 1 end
        if not self.done[2] then return 2 end
        return nil
    end
    if not self.done[1] then return 1 end
    if self.mode == 'versus' and not self.done[2] then return 2 end
    return nil
end

local function move(i, dx, dy, n)
    local COLS=math.min(MAX_COLS,n)
    local row, col = (i - 1) // COLS, (i - 1) % COLS
    local rows = math.ceil(n / COLS)
    col = (col + dx) % COLS
    row = (row + dy) % rows
    local j = row * COLS + col + 1
    if j > n then j = n end
    return j
end

function S:confirm(p)
    local app = self.app
    if self.roster[self.cur[p]].selectionOnly then self.notice='此角色暂供选人预览';return end
    self.done[p] = true
    app.audio:play(app.audio.ID.okBig)
    local c = self.roster[self.cur[p]]
    app.audio:play(app.audio.ID.ecast[c.element])
    self.flash = self.flash or {0, 0}
    self.flash[p] = 16
    if not self:activePlayer() then self:afterChars() end
end

function S:afterChars()
    self.roster=self.roster or Art.roster
    self.stageI=1
    if self.mode=='training' then
        self.cur[2]=(self.cur[1] % #Art.roster)+1
        self.done[2]=true
    end
    self:launch()
    if self.mode~='online' then self.phase='go' end
end

function S:launch()
    local app = self.app
    if self.mode=='online' then
        if O.isHost(self.net) then self.net.host.stage=1 end
        self.net.me.ready=true; self.phase='wait'
        return
    end
    local mine = self.roster[self.cur[1]].key
    if self.mode == 'arcade' then
        local arcade=require('gf_mode_arcade').new(mine,Art.roster,app.t)
        app:travel('vs', {arcade = arcade})
        return
    end
    local st = Stage.order[self.stageI] or Stage.order[1]
    local args = {chars = {mine, self.roster[self.cur[2]].key}, stage = st, mode = self.mode}
    if self.mode == 'training' then
        args.mode = 'training'
        args.cpu = {false, false}
    elseif self.args.cpu then
        args.cpu = {false, app.settings.cpu}
    else
        args.cpu = {false, false}
    end
    app:travel('vs', args)
end

function S:tick()
    local app = self.app
    self.t = self.t + 1 / 60
    if self.phase=='go' then return end
    self.frameN = (self.frameN or 0) + 1
    -- the backdrop builds slowly while the card bitmaps are still being drawn (frame budget)
    if self.bd then self.bd:step(self.built < #self.roster and 40 or 300) end
    -- the first frame creates every layer node; cards and fighters start on the next ones
    if self.frameN >= 2 then self:buildCards() end
    local acts = app.input:menu()
    local n = #self.roster
    if self.net then
        self.net.me.char=self.cur[1]
        if O.isHost(self.net) then self.net.host.stage=self.stageI end
        local opp=O.opponent(self.net); local peer=opp and self.net.peers[opp]
        if not peer then
            self.net.me.ready=false; self.net.me.selecting=false
            app:travel('online'); return
        end
        self.cur[2]=math.max(1,math.min(n,peer.lobby.char))
        self.done[2]=peer.lobby.ready
        if not O.isHost(self.net) then self.stageI=O.parseSetup(peer.setup).stage end
        local function opts(chars,setup,seed)
            return {chars={self.roster[chars[1]],self.roster[chars[2]]},rounds=setup.rounds,time=setup.time,seed=seed}
        end
        local onFrame=function(st,f,re) if self.net.onFrame then self.net.onFrame(st,f,re) end end
        local m
        if O.isHost(self.net) and O.bothReady(self.net) then m=O.hostStart(self.net,onFrame,opts)
        elseif not O.isHost(self.net) then m=O.checkJoin(self.net,onFrame,opts) end
        if m then
            self.phase='go'
            app:travel('vs',{chars={self.roster[m.roster.chars[1]].key,self.roster[m.roster.chars[2]].key},
                stage=Stage.order[m.setup.stage],mode='online',online=true,rounds=m.setup.rounds,time=m.setup.time})
            return
        end
    end
    if self.phase == 'chars' then
        -- 2P: player 2 uses its own pad edges
        if self.twoP and not self.done[2] then
            local p2 = app.input:pad(2)
            local pr = p2.pressed or 0
            if pr & 4 ~= 0 then self.cur[2] = move(self.cur[2], -1, 0, n); app.audio:play(app.audio.ID.move) end
            if pr & 8 ~= 0 then self.cur[2] = move(self.cur[2], 1, 0, n); app.audio:play(app.audio.ID.move) end
            if pr & 1 ~= 0 then self.cur[2] = move(self.cur[2], 0, -1, n); app.audio:play(app.audio.ID.move) end
            if pr & 2 ~= 0 then self.cur[2] = move(self.cur[2], 0, 1, n); app.audio:play(app.audio.ID.move) end
            if pr & 16 ~= 0 then self:confirm(2) end
        end
        local p = self.twoP and (not self.done[1] and 1 or nil) or self:activePlayer()
        for _, a in ipairs(acts) do
            if p then
                if a == 'left' then self.cur[p] = move(self.cur[p], -1, 0, n); app.audio:play(app.audio.ID.move)
                elseif a == 'right' then self.cur[p] = move(self.cur[p], 1, 0, n); app.audio:play(app.audio.ID.move)
                elseif a == 'up' then self.cur[p] = move(self.cur[p], 0, -1, n); app.audio:play(app.audio.ID.move)
                elseif a == 'down' then self.cur[p] = move(self.cur[p], 0, 1, n); app.audio:play(app.audio.ID.move)
                elseif a == 'ok' then self:confirm(p)
                elseif a == 'alt' then self.cur[p] = (math.floor(self.t * 977) % n) + 1; self:confirm(p) end
            end
            if a == 'back' then
                if self.net then
                    self.net.me.ready=false; self.net.me.selecting=false
                    if self.net.io.stop then self.net.io.stop() end
                    app.net=nil; app:travel('menu')
                elseif self.done[2] and not self.twoP then self.done[2] = false
                elseif self.done[1] then self.done[1] = false
                else
                    if self.net then
                        if self.net.io.stop then self.net.io.stop() end
                        app.net=nil
                    end
                    app:travel('menu')
                end
                app.audio:play(app.audio.ID.back)
            end
        end
    elseif self.phase=='wait' then
        for _,a in ipairs(acts) do
            if a=='back' then
                self.net.me.ready=false; self.done[1]=false; self.phase='chars'
                app.audio:play(app.audio.ID.back)
            end
        end
    end
end

-- at most one fighter bitmap is (re)built per frame (a hi-tier pose is ~1200 rects)
function S:previews()
    local app = self.app
    local built = false
    for p = 1, 2 do
        local show = self.shows[p]
        local focused = self:activePlayer() or 1
        local visible = p == focused
        if visible then
            local key = self.roster[self.cur[p]].key
            if self.roster[self.cur[p]].selectionOnly then
                local img=self.previewArt.pose(key,self.tier,'idle')
                if self.shown[p]~=key then
                    self.shown[p]=key;show.bmp:start(img,key);show.bmp.node:on(false)
                    self.swapT=self.swapT or {0,0};self.swapT[p]=0
                end
                if show.bmp:step(200) then
                    show.bmp.node:pos(-(app.W/2-330),-app.H/2+372):scale(1.2):on(true)
                end
            else
            local pose = self.done[p] and 'special' or 'idle'
            local want = key .. pose
            if self.shown[p] ~= want and not built then
                built = true
                self.shown[p] = want
                self.swapT = self.swapT or {0, 0}
                self.swapT[p] = 0
                local side = p == 1 and -1 or 1
                show:set(key, self.tier, pose, -(app.W / 2 - 330), -app.H / 2 + 372, 1.2, 1, 0)
                local n = show.bmp.node
                local x0 = n.x
                n:pos(x0 + side * 120, n.y)
                n:tween({anchoredPositionX = x0}, 0.3, 'OutCubic')
            end
            end
        else
            show:hide()
            self.shown[p] = nil
        end
    end
end

-- The currently selected fighter stays on the left; its information fills the right panel.
local function nameBlock(L, c, W, H, a, done, player, team)
    local ec = UI.ECOL[c.element] or K.elementColor[c.element]
    local bx, y = W / 4, H / 2 - 220
    if team then bx=bx-280 end
    local width = math.min(760, W / 2 - 180)
    if not team then UI.slab(L, bx, H / 2 - 290, width + 70, 410, UI.NAVY, 0.88 * a, -UI.SLANT) end
    L:label(UI.track((K.en[c.key] or ''):upper()), bx, y + 70, width, 26, 16, UI.GOLD, 'l', nil, a)
    if team then team:drawNameAction(L,c,bx,y+8,width,a)
    else L:label(c.name, bx, y + 8, width, 100, 78, UI.WHITE, 'l', nil, a) end
    L:rect(bx, y - 48, width, 2, ec, a)
    L:label((K.title[c.key] or '') .. ' · ' .. (K.elementName[c.element] or '') .. '元素 · ' .. (K.weaponName[c.weapon] or ''),
            bx, y - 76, width, 28, 19, UI.GREY, 'l', nil, a)
    if team then
        local skillLeft=bx-width/2+360
        L:label('E  ' .. c.skill,skillLeft+200,y+30,400,30,20,UI.CREAM,'l',nil,a)
        L:label('Q  ' .. c.burst,skillLeft+200,y-10,400,30,20,UI.CREAM,'l',nil,a)
    else
        L:label('E  ' .. c.skill,bx,y-118,width,30,22,UI.CREAM,'l',nil,a)
        L:label('Q  ' .. c.burst,bx,y-156,width,30,22,UI.CREAM,'l',nil,a)
    end
    if not team then L:label(player == 2 and '选择电脑对手' or '选择你的角色', bx, y - 202, width, 28, 18, UI.GOLD, 'l', nil, a) end
    local da = done and a or 0
    UI.slab(L, -(W / 2 - 330), -H / 2 + 560, 330, 50, UI.CREAM, 0.95 * da, 8)
    L:label('已确定 READY', -(W / 2 - 330), -H / 2 + 560, 330, 50, 24, UI.TEXT, 'c', nil, da)
end

function S:draw()
    local app = self.app
    local W, H = app.W, app.H
    local t = self.t
    if self.bd then self.bd:draw(self.phase == 'stage' and 0.25 or 0.5, {10, 14, 32}) end
    if (self.frameN or 0) >= 3 then self:previews() end
    local sideOn = {true, self.mode ~= 'arcade' and not (self.mode == 'training' and not self.done[1])}
    if self.teams then sideOn[2]=false end
    -- backdrop graphics: per-side slabs, ghost names, the roster band
    local B = self.Lback
    B:begin()
    local focused = self:activePlayer() or 1
    for _, p in ipairs({focused}) do
        local side = -1
        local c = self.roster[self.cur[p]]
        local ec = UI.ECOL[c.element] or K.elementColor[c.element]
        local a = 1
        self.swapT = self.swapT or {0, 0}
        self.swapT[p] = (self.swapT[p] or 0) + 1
        local k = U.ease.outCubic(U.clamp(self.swapT[p] / 14, 0, 1))
        local sx = side * (W / 2 - 150)
        UI.slab(B, sx, 0, 520, H * 1.9, U.mix(ec, UI.NAVY, 0.78), 0.72 * a, side * UI.SLANT)
        UI.stripes(B, sx, 0, 420, H * 1.9, 12, UI.WHITE, 0.03 * a, side * UI.SLANT)
        UI.slab(B, sx - side * 270, 0, 3, H * 2, UI.GOLD, 0.7 * a, side * UI.SLANT)
        UI.slab(B, sx - side * 298, 0, 10, H * 2, ec, 0.45 * a, side * UI.SLANT)
        B:shape(G.ELLIPSE, side * (W / 2 - 330), -H / 2 + 560, 560, 620, ec, 0.24 * a, 0, 0.5)
        B:shape(G.ELLIPSE, side * (W / 2 - 330), -H / 2 + 372, 380, 40, {0, 0, 0}, 0.5 * a, 0, 0.5)
        local gname = (K.en[c.key] or ''):upper()
        local g = B:label(gname, side * (W / 2 - 300) + side * (1 - k) * 120, -40, 1400, 260, 190, UI.WHITE, 'c', nil, 0.07 * a * k)
        g:rot(90)
    end
    -- band behind the roster
    if self.teams then
        local width=math.min(760,W/2-180)
        UI.slab(B,W/4-410,H/2-270,width+70,350,UI.NAVY,.88,-UI.SLANT)
    end
    local gy = -H / 2 + 272 - (CARD_H + GAP) / 2
    B:rect(0, gy, W + 60, 2 * CARD_H + GAP + 56, UI.NAVY, 0.82)
    B:rect(0, gy + CARD_H + GAP / 2 + 28, W + 60, 2, UI.GOLD, 0.7)
    B:rect(0, gy - CARD_H - GAP / 2 - 28, W + 60, 2, UI.GOLD, 0.4)
    -- card backs
    for i, c in ipairs(self.roster) do
        local x, y = self:cardPos(i)
        local ec = UI.ECOL[c.element] or K.elementColor[c.element]
        local hot = (i == self.cur[1]) or (sideOn[2] and i == self.cur[2])
        B:rect(x, y, CARD_W, CARD_H, hot and U.mix(ec, UI.NAVY, 0.45) or UI.NAVY2, 1)
        B:rect(x, y + 14, CARD_W, CARD_H - 28, U.mix(ec, UI.NAVY2, 0.7), 1)
        B:shape(G.ELLIPSE, x, y + 24, CARD_W * 1.1, CARD_H * 0.8, ec, hot and 0.45 or 0.18, 0, 0.5)
    end
    if self.drawTeamBacks then self:drawTeamBacks(B) end
    B:finish()
    local L = self.L
    L:begin()
    -- card fronts: name band, element mark, dim when not hot
    for i, c in ipairs(self.roster) do
        local x, y = self:cardPos(i)
        local ec = UI.ECOL[c.element] or K.elementColor[c.element]
        local hot = (i == self.cur[1]) or (sideOn[2] and i == self.cur[2])
        L:rect(x, y - CARD_H / 2 + 14, CARD_W, 28, hot and UI.CREAM or UI.NAVY, hot and 1 or 0.92)
        L:rect(x, y - CARD_H / 2 + 29, CARD_W, 3, ec, 1)
        local label=self.cardLabel and self:cardLabel(i,c) or c.name
        if not self.cardLabel then local p=self:activePlayer();if p and self.focused[p] and self.cur[p]==i then label=c.selectionOnly and '预览' or '确认' end end
        L:label(label, x, y - CARD_H / 2 + 14, CARD_W, 28, 15, hot and UI.TEXT or UI.WHITE, 'c', nil, 1)
        UI.element(L, c.element, x + CARD_W / 2 - 15, y + CARD_H / 2 - 15, 18, 0.95)
        L:rect(x, y + 14, CARD_W, CARD_H - 28, UI.NAVY, hot and 0 or 0.28)
    end
    for i, b in pairs(self.cards) do
        local hot = (i == self.cur[1]) or (sideOn[2] and i == self.cur[2])
        b.node:scale(hot and 1.04 or 1, hot and 1.04 or 1)
    end
    -- cursors: thick frame + tilted tag
    if self.drawMarkers then self:drawMarkers(L) else
    for p = 1, 2 do
        local x, y = self:cardPos(self.cur[p])
        local col = PCOL[p]
        local pulse = 0.75 + 0.25 * math.sin(t * 9 + p)
        local a = sideOn[p] and (self.done[p] and 1 or pulse) or 0
        local off = (p == 2 and self.cur[1] == self.cur[2]) and 5 or 0
        local fw, fh = CARD_W + 8 + off * 2, CARD_H + 8 + off * 2
        L:rect(x, y + fh / 2, fw + 5, 5, col, a)
        L:rect(x, y - fh / 2, fw + 5, 5, col, a)
        L:rect(x - fw / 2, y, 5, fh, col, a)
        L:rect(x + fw / 2, y, 5, fh, col, a)
        local tx = x + (p == 1 and -24 or 24)
        local ty = y + fh / 2 - 12
        UI.slab(L, tx, ty, 58, 26, col, a, 8)
        local tag = self.net and (p==1 and '你' or '对手') or (p == 1 and '1P' or (self.twoP and '2P' or 'CPU'))
        L:label(tag, tx, ty, 58, 26, 16, UI.TEXT, 'c', nil, a)
    end
    end
    -- header (top centre)
    local titles = {teamOnline='ONLINE TEAM',teamSolo='TEAM BATTLE',online='ONLINE VERSUS',arcade = 'ARCADE', versus = self.twoP and 'LOCAL VERSUS' or 'VERSUS CPU', training = 'TRAINING'}
    local headerX=self.teams and 80 or 0
    L:label('选择角色', headerX, H / 2 - 56, 400, 56, 40, UI.WHITE, 'c', nil, 1)
    L:label(UI.track(titles[self.mode] or ''), headerX, H / 2 - 96, 400, 24, 14, UI.GOLD, 'c', nil, 1)
    L:shape(G.RECT, headerX-150, H / 2 - 96, 7, 7, UI.GOLD, 1, 45)
    L:shape(G.RECT, headerX+150, H / 2 - 96, 7, 7, UI.GOLD, 1, 45)
    -- Only the active pick is described, in the right-hand frame.
    local infoPlayer = self:activePlayer() or 1
    local c = self.roster[self.cur[infoPlayer]]
    local k = U.ease.outCubic(U.clamp((self.swapT[infoPlayer] or 0) / 12, 0, 1))
    nameBlock(L, c, W, H, (self.phase == 'chars' or self.phase=='wait') and k or 0, self.done[infoPlayer], infoPlayer,self.teams and self)
    if self.net then
        local peer=self.net.peers[O.opponent(self.net)]
        local name=self.roster[self.cur[2]].name
        L:label('对手：'..name..(self.done[2] and ' · 已准备' or ' · 选人中'),0,H/2-132,800,34,20,UI.CREAM,'c')
        if self.phase=='wait' then
            UI.slab(L,0,-H/2+350,800,52,UI.NAVY,.95,0)
            L:label('已准备 · 等待对手确认角色',0,-H/2+350,800,52,24,UI.WHITE,'c')
        end
    end
    -- prompts
    UI.prompt(L, W / 2 - 460, -H / 2 + 30, 'J', '确认', 1, 'ok')
    UI.prompt(L, W / 2 - 300, -H / 2 + 30, 'K', '返回', 1, 'back')
    UI.prompt(L, W / 2 - 140, -H / 2 + 30, 'L', '随机', 1, 'alt')
    if self.drawTeamBars then self:drawTeamBars(L) end
    L:finish()
end

function S:exit()
    for _, b in pairs(self.cards) do b:free() end
    G.release(self.cardsG)
    self.Lback:free()
    self.L:free()
    for _, s in ipairs(self.shows) do s:free() end
end

return S
end
__loaders['gf_scene_team_select'] = function()
-- First UI revision: retain the existing roster layout, add numbered player tags only.
local Base=require('gf_scene_select')
local UI=require('gf_ui')
local Art=require('gf_selection_art')
local G=require('gf_gfx')
local T=setmetatable({}, {__index=Base});T.__index=T
local colors={{255,196,92},{98,200,255}}

function T.new(app,args)
    return setmetatable({app=app,args=args,initFrames=0},T)
end
function T:initialize()
    local originalArgs=self.args
    local full=Base.new(self.app,{mode='versus',cpu=true,previewRoster=true})
    for k,v in pairs(full) do self[k]=v end
    self.args=originalArgs
    self.mode=self.args.teamOnline and 'teamOnline' or 'teamSolo'
    self.teams={{},{}};self.edit=1;self.phase='chars';self.notice=''
    self.ready={false,false};self.focused=false;self.cpuAt=.7
    self.thumbs={{},{}};self.thumbKeys={{},{}}
    self.opponentTag=self.args.cpu==false and '2P' or 'CPU'
    self.cur={1,1}
    self.app.input:clearUI()
    self:bindAreas()
    self.initialized=true
    if self.args.teamOnline then
        self.app.teamSelectionIO=self.app.teamSelectionIO or self.app.env.teamio or require('gf_team_selection').new(self.app.env.game,self.app.env.script,function()return self.app.t end)
        self.teamIO=self.app.teamSelectionIO;self.teamIO.start();self.netEpoch=self.teamIO.epoch
    end
end
function T:activePlayer() return self.edit end
function T:bindAreas()
    self.cardAreas={}
    for i=1,#Art.roster do
        local idx=i;local x,y=self:cardPos(i)
        self.cardAreas[i]=self.app.input:area(x,y,104,128,{down=function()
            if #self.teams[1]<3 and not self.ready[1] then
                if self.cur[1]==idx and self.focused and not self:inTeam(idx) then self:confirm()
                else self.cur[1]=idx;self.focused=true;self.notice='' end
            end
        end})
    end
end
function T:inTeam(idx)
    for _,v in ipairs(self.teams[1]) do if v==idx then return true end end
    return false
end
function T:confirm()
    if self.teamIO and not self.teamIO.slot then self.notice='等待联机席位';return end
    local team=self.teams[1];local idx=self.cur[1]
    if #team==3 then
        self.ready[1]=not self.ready[1];self.startAt=nil
        self.notice=self.ready[1] and '已准备 · 等待对方' or '已取消准备'
        if self.teamIO then self.teamIO.publish(team,self.ready[1]) end
        return
    end
    if not self.focused then self.focused=true;return end
    for _,v in ipairs(team) do if v==idx then self.notice='该角色已选择';return end end
    if #team>=3 then return end
    team[#team+1]=idx;self.notice='';self.app.audio:play(self.app.audio.ID.okBig)
    self.focused=false
    if self.teamIO then self.teamIO.publish(team,false) end
end
function T:action(a)
    local p=self.edit;local team=self.teams[p]
    if a=='ok' then self:confirm()
    elseif a=='back' then
        self.notice=''
        if self.ready[1] then self.ready[1]=false;self.startAt=nil
        elseif #team>0 then self.cur[p]=table.remove(team);self.focused=true
        else self.app:travel('menu') end
        if self.teamIO then self.teamIO.publish(team,self.ready[1]) end
    elseif a=='alt' then
        local start=math.floor(self.t*977)%#Art.roster+1
        for n=0,#Art.roster-1 do
            local idx=(start+n-1)%#Art.roster+1;local exists=false
            for _,v in ipairs(team) do if v==idx then exists=true end end
            if not exists then self.cur[p]=idx;self.focused=true;break end
        end
    elseif a=='left' or a=='right' or a=='up' or a=='down' then
        local d=(a=='left' or a=='up') and -1 or 1
        if #team<3 then self.cur[p]=(self.cur[p]-1+d)%#Art.roster+1;self.focused=true end
    end
end
function T:tick()
    if not self.initialized then
        self.initFrames=self.initFrames+1
        if self.initFrames>=2 then self:initialize() end
        return
    end
    self.t=self.t+1/60;self.frameN=(self.frameN or 0)+1
    self.loadingPose=false
    for _,a in ipairs(self.app.input:menu()) do self:action(a) end
    -- Local CPU chooses privately; only its count/ready status reaches the selection view.
    if not self.teamIO and #self.teams[2]<3 and self.t>=self.cpuAt then
        local idx=(#self.teams[2]*2+math.floor(self.cpuAt*17))%#Art.roster+1
        local used={};for _,v in ipairs(self.teams[2]) do used[v]=true end
        while used[idx] do idx=idx%#Art.roster+1 end
        self.teams[2][#self.teams[2]+1]=idx;self.cpuAt=self.t+.7
        self.ready[2]=#self.teams[2]==3
    end
    if self.teamIO then
        self.teamIO.pump()
        if self.netEpoch~=self.teamIO.epoch then
            self.netEpoch=self.teamIO.epoch;self.teams[1]={};self.ready[1]=false;self.startAt=nil;self.focused=false
        end
        self.ready[2]=self.teamIO.remoteReady
    end
    if self.ready[1] and self.ready[2] and (not self.teamIO or self.teamIO.reveal) then
        self.startAt=self.startAt or self.t+1
        if self.t>=self.startAt and not self.leaving then
            self.leaving=true
            local source=self.teamIO and self.teamIO.reveal or self.teams
            local copy={{},{}};for q=1,2 do for n,v in ipairs(source[q]) do copy[q][n]=v end end
            self.app:travel('gf_scene_team_vs',{teams=copy,teamOnline=self.args.teamOnline,teamIO=self.teamIO})
        end
    end
    local p=self.edit;local key=Art.roster[self.cur[p]].key
    -- Decode and build the single large preview on separate callbacks.
    if self.frameN>=3 and (self.previewKey~=key or self.previewPlayer~=p) then
        self.previewKey=key;self.previewPlayer=p
        self.previewImage=Art.pose(key,self.tier,'idle')
        self.shows[p].bmp:start(self.previewImage,key..':team-idle')
        self.shows[p].bmp.node:on(false);self.shows[3-p]:hide()
        self.loadingPose=true;return
    end
    if self.bd then self.bd:step(self.built<#Art.roster and 40 or 300) end
    if self.frameN>=2 then self:buildCards() end
    if self.built==#Art.roster then
        for q=1,1 do for n=1,3 do
            local idx=self.teams[q][n]
            if self.thumbKeys[q][n]~=idx then
                local b=self.thumbs[q][n]
                if idx then
                    if not b then b=G.bitmap(self.cardsG);self.thumbs[q][n]=b end
                    local face=Art.face(Art.roster[idx].key)
                    b:drawMany({{img=face,ox=0,oy=-22,s=44/face.h}})
                elseif b then b.node:on(false) end
                self.thumbKeys[q][n]=idx;return
            end
        end end
    end
end
function T:teamBarPos(p,n)
    local W,H=self.app.W,self.app.H
    local originalWidth=math.min(1040,W/2+60)
    local originalSlot=(originalWidth-220)/3-12
    local step=originalSlot/2+12
    local w=220+3*step
    local textWidth=math.min(760,W/2-180)
    local left=W/4-280-textWidth/2
    local x,y=left+w/2,-H/2+432+(p==1 and 72 or 0)
    if not n then return x,y,w end
    return x-w/2+220+(n-.5)*step,y+7,step-12
end
function T:drawTeamBacks(B)
    if (self.frameN or 0)<6 then return end
    for p=1,1 do
        local x,y,w=self:teamBarPos(p)
        UI.parallelogram(B,x,y,w,70,UI.NAVY,.96,UI.GOLD)
        for n=1,3 do local sx,sy,sw=self:teamBarPos(p,n)
            UI.parallelogram(B,sx,sy,sw,48,UI.NAVY2,1,UI.GOLD)
        end
    end
end
function T:drawTeamBars(L)
    if (self.frameN or 0)<7 then return end
    for p=1,1 do
        local x,y,w=self:teamBarPos(p);local left=x-w/2
        UI.parallelogram(L,left+48,y+8,64,26,colors[p],1)
        L:label(self.teamIO and (self.teamIO.slot and self.teamIO.slot..'P' or '…') or '1P',left+48,y+8,64,26,17,UI.TEXT,'c')
        L:label('阵容  '..#self.teams[p]..'/3',left+148,y+8,128,26,18,UI.GOLD,'c')
        for n=1,3 do
            local sx,sy,sw=self:teamBarPos(p,n);local idx=self.teams[p][n]
            local b=self.thumbs[p][n]
            if b then b.node:pos(sx,sy):on(idx~=nil and self.thumbKeys[p][n]==idx) end
            L:label(tostring(n),sx-sw/2+14,sy+8,24,24,14,UI.CREAM,'c')
            if not idx then L:label('+',sx,sy,sw,32,25,UI.GOLD,'c') end
        end
        local count=self.teamIO and self.teamIO.remoteCount or #self.teams[2]
        local status=self.ready[2] and '对方已准备' or ('对方已选 '..count..'/3')
