        p.skillCd, p.stun, p.hitstop, p.invul, p.coat, p.vuln, p.shield, p.frozen = 0, 0, 0, 0, 0, 0, 0, 0
        p.dots = {}
        p.combo, p.comboDmg, p.juggle = 0, 0, 0
        p.move, p.airMove, p.bufferedMove = nil, nil, nil
