    liyue = {kind = 'rocks', col = {44, 30, 18}, motes = {shape = ELLIPSE, col = {255, 196, 70}, n = 8, size = 34, move = 'fall', leaf = true}},
    inazuma = {kind = 'grass', col = {34, 20, 46}, motes = {shape = ELLIPSE, col = {255, 176, 214}, n = 9, size = 30, move = 'fall', leaf = true}},
