end

function U.mix(c1, c2, t)
    return {c1[1] + (c2[1] - c1[1]) * t, c1[2] + (c2[2] - c1[2]) * t, c1[3] + (c2[3] - c1[3]) * t,
            (c1[4] or 255) + ((c2[4] or 255) - (c1[4] or 255)) * t}
