__loaders['gf_character_registry']=function()
-- Stable roster indices are also protocol IDs. Append; never sort by display name.
local R={definitions={
 {key='raidenshogun',name='雷电将军',element='electro',weapon='polearm',attack='源流',skill='神变·恶曜开眼',burst='奥义·梦想真说',h=336},
 {key='nahida',name='纳西妲',element='dendro',weapon='catalyst',attack='行相',skill='所闻遍计',burst='心景幻成',h=261},
 {key='furina',name='芙宁娜',element='hydro',weapon='sword',attack='独舞之邀',skill='孤心沙龙',burst='万众狂欢',h=335,candidate=true,provider='gf_character_furina'},
 {key='kamisatoayaka',name='神里绫华',element='cryo',weapon='sword',attack='神里流·倾',skill='神里流·冰华',burst='神里流·霜灭',h=335,candidate=true,provider='gf_character_ayaka'},
 {key='clorinde',name='克洛琳德',element='electro',weapon='sword',attack='逐影之誓',skill='狩夜之巡',burst='残光将终',h=335,candidate=true,provider='gf_character_clorinde'},
 {key='arlecchino',name='阿蕾奇诺',element='pyro',weapon='polearm',attack='斩首之邀',skill='万相化灰',burst='厄月将升',h=335,candidate=true,provider='gf_character_arlecchino'},
},byKey={},providers={}}
for i,c in ipairs(R.definitions) do
 assert(not R.byKey[c.key],'duplicate character key')
 c.index=i;R.byKey[c.key]=c
end
function R.provider(key)
 local c=R.byKey[key]
 if not c or not c.provider then return nil end
 if not R.providers[key] then R.providers[key]=require(c.provider) end
 return R.providers[key]
end
return R
end
__loaders['gf_character_assets']=function()
local U=require('gf_util')
local M={}
-- Provider boundary: encoded storage can change without changing Art/FView callers.
function M.new(data)
 local P={data=data,bodyPeak=data.bodyPeak}
 local function commit(img,raw)
  local values=U.rectangleValues(img,raw)
  for i=1,img.n*5 do
   local v=values[i]
   local axis=i%5;values[i]=axis==0 and v or v*((axis==1 or axis==3) and (img.ux or img.u) or (img.uy or img.u))
  end
  img.bytes=values;img.ax=img.ax*(img.ux or img.u);img.ay=img.ay*(img.uy or img.u)
  img.w=img.w*(img.ux or img.u);img.h=img.h*(img.uy or img.u);img.seam=.08*img.u;img.u=1;img.baked=true
 end
 function P.image(pose)
  local id=data.aliases[pose] or pose
  local img=assert(data.frames[id],'missing character image: '..tostring(pose))
  if not img.bytes then commit(img,U.decodeImage(img)) end
  return img
 end
 function P.prepare()
  if GF_RAW_ASSET_TABLES then return {total=0,completed=0,step=function()return true end} end
  local names={}
  for id,img in pairs(data.frames) do if not img.bytes then names[#names+1]=id end end
  table.sort(names)
  local job={i=1,total=#names,completed=0}
  function job:step(budget)
   local id=names[self.i];if not id then return true end
   local img=data.frames[id]
   -- Menu preview or another preparation job may have committed this image.
   if not img.bytes then
    self.decoder=self.decoder or U.imageDecoder(img)
    if not self.decoder:step(math.max(4,math.min(9000,budget or 9000))) then return false end
    commit(img,self.decoder.bytes)
   end
   self.decoder=nil;self.completed=self.i;self.i=self.i+1
   return self.i>self.total
  end
  return job
 end
 return P
end
return M
end
__loaders['gf_character_furina']=function()
local Asset=require('gf_character_assets')
local D=require('gf_furina_data')
local P=Asset.new(D)
local moves={light1='light1',light2='light2',light3='light3',heavy='heavy',crouchLight='crouchLight',crouchHeavy='crouchHeavy',airLight='airLight',airHeavy='airHeavy'}
local function total(group)
 local n=0;for _,d in ipairs(group.durations) do n=n+d end;return n
end
local function sample(id,t,loop)
 local g=assert(D.groups[id],id)
 if loop then t=t%total(g) end
 for i,d in ipairs(g.durations) do
  if t<d then return g.frames[i],i end;t=t-d
 end
 return g.frames[#g.frames],#g.frames
end
-- Delivered animation time is preserved. The character rule adapter uses the same clock.
local function moveTime(id,t,m)
 return t
end
function P.poseFor(view)
 local f=view.f;local st,t=f.state,f.t
 if f.foe.key=='furina' and f.foe.state=='burst' and f.foe.cinematicConfirmed then
  return D.groups.hurt.frames[f.foe.t>=122 and 4 or f.foe.t>=56 and 3 or 1]
 end
 if f.foe.key=='kamisatoayaka' and f.foe.state=='burst' and f.foe.cinematicConfirmed then return D.groups.hurt.frames[f.foe.t>=144 and 4 or 3] end
 if f.airMove then local id=moves[f.airMoveId];return sample(id,moveTime(id,f.airT or 0,f.airMove)) end
 if st=='attack' then
  -- The legacy sim reports a failed grab as an attack, without a victim.
  if f.moveId=='throwWhiff' then return sample('throw',math.min(19,t)) end
  local id=assert(moves[f.moveId],f.moveId);return sample(id,moveTime(id,t,f.move))
 end
 if st=='walk' or st=='back' then return sample(st,view.walkT,true) end
 if st=='dash' or st=='backdash' then return sample(st,t) end
 if st=='crouch' then return sample('crouch',t) end
 if st=='jumpsq' then return D.groups.jump.frames[1] end
 if st=='land' then return D.groups.jump.frames[6] end
 if st=='air' then return sample('jump',f.flightT or t) end
 if st=='block' or st=='cblock' then return D.groups[st].frames[t<8 and 4 or 5] end
 if st=='hit' then return D.groups.hurt.frames[1] end
 if st=='airhit' then return D.groups.hurt.frames[3] end
 if st=='down' then return D.groups.hurt.frames[4] end
 if st=='getup' then return sample('getup',t) end
 if st=='skill' then return sample('skill',moveTime('skill',t,f.move)) end
 if st=='burst' then return sample('burst',t) end
 if st=='throw' then return sample('throw',t) end
 if st=='thrown' then return sample('thrown',f.foe.key=='furina' and f.foe.t or t/30*total(D.groups.thrown)) end
 if st=='win' then return sample('win',t) end
 if st=='lose' then return sample('lose',t) end
 return sample('idle',t,true)
end
P.groundedFrames=true
-- Native feedback: walk looks smaller than idle. The delivered fitted silhouettes
-- are 70 versus 80 pixels high in their reference poses, both at 4.5 units/pixel.
-- One fixed locomotion correction preserves the six-frame gait and foot anchors;
-- never resize each frame from its weapon/effect bounding box.
function P.displayScale(view) return 1 end
P.sample=sample
function P.nextLocomotion(view)
 local g=D.groups[view.f.state];if not g then return nil end
 local t=view.walkT%total(g)
 for i,d in ipairs(g.durations) do
  if t<d then return g.frames[i%#g.frames+1] end;t=t-d
 end
end
require('gf_character_furina_view')(P,D)
return P
