}
local R = {}
local function pair(a, b, r) R[a] = R[a] or {}; R[b] = R[b] or {}; R[a][b] = r; R[b][a] = r end
pair('hydro', 'pyro', 'vaporize')
pair('cryo', 'pyro', 'melt')
pair('electro', 'pyro', 'overload')
pair('hydro', 'cryo', 'frozen')
pair('electro', 'hydro', 'electro')
