pair('dendro', 'pyro', 'burning')
for _, e in ipairs({'hydro', 'pyro', 'electro', 'cryo'}) do
    R.anemo = R.anemo or {}; R.anemo[e] = 'swirl'; R[e].anemo = 'swirl'
