__loaders['gf_character_ayaka']=function()
local Asset=require('gf_character_assets')
local D=require('gf_ayaka_data')
local P=Asset.new(D)
local moves={light1='light1',light2='light2',light3='light3',heavy='heavy',crouchLight='crouchLight',crouchHeavy='crouchHeavy',airLight='airLight',airHeavy='airHeavy'}
local function total(group)
 local n=0;for _,d in ipairs(group.durations) do n=n+d end;return n
end
local function sample(id,t,loop)
 local g=assert(D.groups[id],id)
 if loop then t=t%total(g) end
 for i,d in ipairs(g.durations) do
  if t<d then return g.frames[i],i end;t=t-d
 end
 return g.frames[#g.frames],#g.frames
end
-- Delivered animation time is preserved. The character rule adapter uses the same clock.
local function moveTime(id,t,m)
 return t
end
function P.poseFor(view)
 local f=view.f;local st,t=f.state,f.t
 if f.foe.key=='furina' and f.foe.state=='burst' and f.foe.cinematicConfirmed then
  return D.groups.hurt.frames[f.foe.t>=122 and 4 or f.foe.t>=56 and 3 or 1]
 end
 if f.foe.key=='kamisatoayaka' and f.foe.state=='burst' and f.foe.cinematicConfirmed then return D.groups.hurt.frames[f.foe.t>=144 and 4 or 3] end
 if f.airMove then local id=moves[f.airMoveId];return sample(id,moveTime(id,f.airT or 0,f.airMove)) end
 if st=='attack' then
  -- The legacy sim reports a failed grab as an attack, without a victim.
  if f.moveId=='throwWhiff' then return sample('throw',math.min(19,t)) end
  local id=assert(moves[f.moveId],f.moveId);return sample(id,moveTime(id,t,f.move))
 end
 if st=='walk' or st=='back' then return sample(st,view.walkT,true) end
 if st=='dash' or st=='backdash' then return sample(st,t/(st=='dash' and 14 or 18)*total(D.groups[st])) end
 if st=='crouch' then return sample('crouch',t) end
 if st=='jumpsq' then return D.groups.jump.frames[1] end
 if st=='land' then return D.groups.jump.frames[6] end
 if st=='air' then return sample('jump',t/32*total(D.groups.jump)) end
 if st=='block' or st=='cblock' then return D.groups[st].frames[t<8 and 3 or 2] end
 if st=='hit' then return D.groups.hurt.frames[1] end
 if st=='airhit' then return D.groups.hurt.frames[3] end
 if st=='down' then return D.groups.hurt.frames[4] end
 if st=='getup' then return sample('getup',t) end
 if st=='skill' then return sample('skill',moveTime('skill',t,f.move)) end
 if st=='burst' then return sample('burst',t) end
 if st=='throw' then return sample('throw',t) end
 if st=='thrown' then return sample('thrown',f.foe.key=='kamisatoayaka' and f.foe.t or t/30*total(D.groups.thrown)) end
 if st=='win' then return sample('win',t) end
 if st=='lose' then return sample('lose',t) end
 return sample('idle',t,true)
end
function P.rootOffset(v)
 if v.f.state~='thrown' then return 0 end
 local _,phase=sample('thrown',v.f.foe.key=='kamisatoayaka' and v.f.foe.t or v.f.t/30*total(D.groups.thrown))
 return ({0,140,100,90,0,0})[phase]
end
P.groundedFrames=true
P.sample=sample
function P.nextLocomotion(view)
 local g=D.groups[view.f.state];if not g then return nil end
 local t=view.walkT%total(g)
 for i,d in ipairs(g.durations) do
  if t<d then return g.frames[i%#g.frames+1] end;t=t-d
 end
end
require('gf_character_ayaka_view')(P,D)
return P
end
__loaders['gf_character_ayaka_rules']=function()
local D=require('gf_ayaka_rules_data')
return function(K)
 local function copy(t)local r={};for k,v in pairs(t) do r[k]=v end;return r end
 local w=copy(K.weapons.sword);w.reach=1
 for _,id in ipairs({'light1','light2','light3','heavy','crouchLight','crouchHeavy','airLight','airHeavy'}) do
  local m=copy(w[id]);local cd=D[id].combat
  m.startup,m.active,m.recovery=cd.startup,cd.active,cd.recovery
  m.box={x=cd.box[1],y=cd.box[2],w=cd.box[3],h=cd.box[4]};m.level=cd.level
  m.lunge=cd.lunge or 0;m.projectile=nil;m.fx=nil;m.airPush=nil
  w[id]=m
 end
 K.characterWeapons=K.characterWeapons or {};K.characterWeapons.kamisatoayaka=w
 K.skills.kamisatoayaka={style='iceBloomDelivered',startup=12,active=8,recovery=18,damage=85,cd=150,hitstun=28,fx='iceBloom'}
 K.bursts.kamisatoayaka={style='soumetsuCinematic',damage=290,hits=3,range=380,fx='soumetsu',confirm=52,finish=152}
 K.body.kamisatoayaka=copy(K.body.default);K.body.kamisatoayaka.getupTicks=40
end
end
__loaders['gf_character_ayaka_view']=function()
local G=require('gf_gfx')
return function(P,D)
 local publish=require('gf_character_effect_channel')(P)
 function P.newView(v,layers)
  local ch={slots={G.bitmap(layers.fx),G.bitmap(layers.fx)},capacity=D.auxPeak}
  for _,b in ipairs(ch.slots) do b.pinned=true;b.node:on(false) end
  v.characterChannels={ch}
 end
 function P.reserveExtras(v,budget)
  for _,b in ipairs(v.characterChannels[1].slots) do
   if #b.kids<D.auxPeak then b:ensure(math.min(D.auxPeak,#b.kids+budget));return false end
  end
  return true
 end
 function P.extras(v)
  local f=v.f;local id,t=f.moveId,f.t
  if f.airMove then id,t=f.airMoveId,f.airT or 0
  elseif f.state=='skill' then id='skill'
  elseif f.state=='burst' then id='burst'
  elseif f.state~='attack' then id=nil end
  local e=id and D.groups[id] and D.groups[id].effects
  if not e or t<e.startTick or t>=e.startTick+e.duration then return {} end
  local age=t-e.startTick;local i=math.min(3,1+math.floor(age/e.duration*3))
  local x,y,face=f.x/100,f.y/100,f.face;local scale,alpha=1,1
  local dx,dy=e.worldOffset[1],-e.worldOffset[2]
  if id=='burst' then
   i=1+math.floor(age/10)%3;dx,dy=230+math.min(145,age*3),205;scale=1.4
   alpha=math.min(1,age/8,math.max(0,(e.duration-age)/14));y=0
  elseif not e.followActor then x=(f.actionX or f.x)/100;y=0 end
  return {{id=e.frames[i],x=x+face*dx,y=y+dy,face=face,scale=scale,alpha=alpha}}
 end
 function P.drawExtras(v)
  local a=P.extras(v)[1];local ch=v.characterChannels[1]
  if a then publish(ch,a.id,a.x,a.y,a.face,a.scale,a.alpha,0,320) else publish(ch) end
 end
 function P.freeView(v)for _,b in ipairs(v.characterChannels[1].slots) do b:free() end end
end
end
__loaders['gf_character_effect_channel']=function()
return function(P)
local function publish(ch,id,x,y,face,scale,alpha,rotation,budget)
  if not id then for _,b in ipairs(ch.slots) do b.node:on(false) end;return end
  local img=P.image(id);local front=ch.front;local back=ch.slots[1]==front and ch.slots[2] or ch.slots[1]
  if not front or front.key~=id then
   if not back.job then back:start(img,id) end
   back:step(budget)
   if not back.job then
    if front then front.node:on(false) end
    ch.front=back;front=back
   end
  end
  if front then
   front.node:pos(x,y):scale(face*(scale or 1),scale or 1):rot(rotation or 0):on(true)
   front:opacity(P.image(front.key),alpha or 1)
  end
 end
return publish
end
end
__loaders['gf_sim_ayaka']=function()
